import { DOCUMENT_KINDS, expect, expectStatus, test, type Document, type Vendor } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test("after a replacement, only the new document waits for review", { tag: "@LIF-05" }, async ({ factory, apiAs }) => {
    // Arrange: a vendor in review, with insurance and contract approved and the w9 rejected.
    const { vendor, documents, extractions } = await factory.vendorInReview({ as: "member" });
    const reviewer = await apiAs("reviewer");
    for (const kind of ["insurance_certificate", "contract"] as const) {
      const decided = await reviewer.post(`/api/extractions/${extractions[kind].id}/decision`, {
        data: { decision: "approve" },
      });
      await expectStatus(decided, 200);
    }
    const rejected = await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "reject", note: "W-9 is unsigned" },
    });
    await expectStatus(rejected, 200);

    const member = await apiAs("member");
    const rejectedVendor = await expectStatus<Vendor>(await member.get(`/api/vendors/${vendor.id}`), 200);
    expect(rejectedVendor.status).toBe("rejected");

    // Act: replace the w9, wait for its extraction, and resubmit.
    const replacement = await factory.upload(vendor.id, "w9", "w9.txt", "member");
    expect(replacement.id).not.toBe(documents.w9.id);

    await expect
      .poll(
        async () => {
          const docs = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
          return docs.find((d) => d.id === replacement.id)?.status;
        },
        { message: "replacement w9 finishes extraction", timeout: 30_000 },
      )
      .toBe("extracted");

    const submitted = await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

    // Assert: the stored vendor is back in review, and the queue lists only the new w9 as pending.
    expect(submitted.status).toBe("in_review");
    const stored = await expectStatus<Vendor>(await member.get(`/api/vendors/${vendor.id}`), 200);
    expect(stored.status).toBe("in_review");

    const queue = await expectStatus<
      { vendor_id: string; extractions: { id: string; kind: (typeof DOCUMENT_KINDS)[number]; status: string }[] }[]
    >(await reviewer.get("/api/review-queue"), 200);
    const item = queue.find((q) => q.vendor_id === vendor.id);
    expect(item, `vendor ${vendor.id} appears in the review queue`).toBeDefined();
    const pending = item!.extractions.filter((e) => e.status === "pending_review");
    expect(pending.map((e) => e.kind)).toEqual(["w9"]);
    expect(pending[0].id).not.toBe(extractions.w9.id);
  });
});
